<script setup lang="ts">
import { useEditorStore } from '../stores/editor';
const editor = useEditorStore();
function reset() { if (editor.layer?.type !== 'image' && editor.layer?.type !== 'asset-image' || editor.layer.locked) return; editor.layer.adjustments = { brightness: 0, contrast: 0, saturation: 0, blur: 0 }; editor.commit(); }
</script>
<template>
  <fieldset v-if="editor.layer?.type === 'image' || editor.layer?.type === 'asset-image'" class="image-adjustments" :disabled="editor.layer.locked"><legend>图片调色</legend><button v-if="!editor.layer.adjustments" type="button" @click="reset">调整色彩</button><template v-else><label>亮度 <output>{{ Math.round(editor.layer.adjustments.brightness * 100) }}</output><input v-model.number="editor.layer.adjustments.brightness" type="range" min="-1" max="1" step=".01" aria-label="图片亮度" @input="editor.commit" /></label><label>对比度 <output>{{ editor.layer.adjustments.contrast }}</output><input v-model.number="editor.layer.adjustments.contrast" type="range" min="-100" max="100" aria-label="图片对比度" @input="editor.commit" /></label><label>饱和度 <output>{{ Math.round(editor.layer.adjustments.saturation * 100) }}</output><input v-model.number="editor.layer.adjustments.saturation" type="range" min="-2" max="2" step=".01" aria-label="图片饱和度" @input="editor.commit" /></label><label>模糊 <output>{{ editor.layer.adjustments.blur }}</output><input v-model.number="editor.layer.adjustments.blur" type="range" min="0" max="30" aria-label="图片模糊" @input="editor.commit" /></label><button type="button" @click="reset">重置调色</button></template></fieldset>
</template>
<style scoped lang="scss">.image-adjustments { border: 0; padding: 0; margin: 14px 0; font-size: 11px; legend { font-weight: 600; } label { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px; margin: 12px 0; } input { width: 100%; } button { padding: 6px 9px; border: 1px solid var(--border); border-radius: 5px; background: var(--surface); font: inherit; } }</style>
